import"./MainLayout.astro_astro_type_script_index_0_lang.DL73JIFh.js";const i=localStorage.getItem("gab_token");function r(e){return e.split(" ").map(o=>o[0]).join("").slice(0,2).toUpperCase()}async function u(){const e=await fetch("/api/cursos",{headers:{Authorization:`Bearer ${i}`}});if(!e.ok)return;const o=await e.json(),a=document.getElementById("grid"),d=document.getElementById("empty-state");if(!o.length){d.style.display="flex";return}a.innerHTML=o.map(t=>{const l=t.total_aulas>0?Math.round(t.aulas_concluidas/t.total_aulas*100):0;return`
        <a href="/curso?id=${t.id}" class="course-card">
          <div class="card-top" style="background:${t.cor||"#6366f1"}">${r(t.titulo)}</div>
          <div class="card-body">
            <div class="card-title">${t.titulo}</div>
            <div class="card-desc">${t.descricao||"<em>Sem descrição</em>"}</div>
            <div class="card-meta">${t.total_modulos} módulo${t.total_modulos!==1?"s":""} · ${t.total_aulas} aula${t.total_aulas!==1?"s":""}</div>
            <div class="prog-wrap"><div class="prog-fill" style="width:${l}%"></div></div>
          </div>
        </a>`}).join("")}let c="#6366f1";const n=document.getElementById("overlay"),m=document.getElementById("btn-novo"),v=document.getElementById("btn-cancel"),s=document.getElementById("btn-criar");m.addEventListener("click",()=>n.classList.remove("hidden"));v.addEventListener("click",()=>n.classList.add("hidden"));n.addEventListener("click",e=>{e.target===n&&n.classList.add("hidden")});document.getElementById("color-picker").addEventListener("click",e=>{const o=e.target.closest(".color-dot");o&&(document.querySelectorAll(".color-dot").forEach(a=>a.classList.remove("sel")),o.classList.add("sel"),c=o.dataset.c)});s.addEventListener("click",async()=>{const e=document.getElementById("inp-titulo").value.trim(),o=document.getElementById("inp-desc").value.trim();if(!e){document.getElementById("inp-titulo").focus();return}s.textContent="Criando…",s.disabled=!0;const a=await fetch("/api/cursos",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${i}`},body:JSON.stringify({titulo:e,descricao:o,cor:c})});if(s.textContent="Criar",s.disabled=!1,a.ok){const{id:d}=await a.json();location.href=`/curso?id=${d}`}});u();
